#!/usr/bin/env node
/*
 * Builds widget/CloudInversionWidget.js — a single self-contained script for
 * the Scriptable iOS app.
 *
 *   node scripts/build-widget.mjs
 *
 * The generated file embeds the shared scoring engine, the Open-Meteo URL
 * builder, and all 38 Bay Area locations. Edit APP_URL near the top after
 * copying it into Scriptable (or set ATC_APP_URL before building).
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

const conditions = fs.readFileSync(path.join(root, "shared", "conditions.js"), "utf8");
const openmeteo = fs.readFileSync(path.join(root, "shared", "openmeteo.js"), "utf8");
const body = fs.readFileSync(path.join(root, "widget", "widget-body.js"), "utf8");
const locations = JSON.parse(fs.readFileSync(path.join(root, "locations.json"), "utf8"));

const defaultLocation = process.env.ATC_DEFAULT_LOCATION || "boccardo-peak";
if (!locations.some((location) => location.id === defaultLocation)) {
  console.error(`Unknown ATC_DEFAULT_LOCATION: ${defaultLocation}`);
  process.exit(1);
}

const appUrl = process.env.ATC_APP_URL || "";

const header = `/*
 * Above the Clouds — Scriptable home-screen widget
 * ================================================
 * Generated by scripts/build-widget.mjs. Do not edit the embedded engine by
 * hand; edit shared/conditions.js or widget/widget-body.js and rebuild.
 *
 * SETUP
 * 1. Install Scriptable (free) from the App Store.
 * 2. Copy this entire file into a new Scriptable script.
 * 3. Set APP_URL below to your deployed app, e.g.
 *      const APP_URL = "https://yourname.github.io/above-the-clouds";
 * 4. Long-press the home screen -> + -> Scriptable -> add a small or medium
 *    widget -> choose this script.
 * 5. Optional: set the widget parameter to a location id (for example
 *    "mount-tamalpais") to show a different peak.
 *
 * The script fetches Open-Meteo directly and keeps a small local cache so the
 * last good forecast still renders if the network is down.
 */
`;

const config = `// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const DEFAULT_LOCATION_ID = ${JSON.stringify(defaultLocation)};
const LOCATIONS = ${JSON.stringify(locations, null, 2)};

`;

const configuredBody = body.replace(
  'const APP_URL = "";',
  `const APP_URL = ${JSON.stringify(appUrl)};`
);
const output = header + config + conditions + "\n" + openmeteo + "\n" + configuredBody;

fs.writeFileSync(path.join(root, "widget", "CloudInversionWidget.js"), output);

const kb = (Buffer.byteLength(output) / 1024).toFixed(1);
console.log(`Wrote widget/CloudInversionWidget.js (${kb} KB, ${locations.length} locations)`);
if (!appUrl) {
  console.log("Tip: set ATC_APP_URL before building, or edit APP_URL in the generated file.");
}
